@Before
    public void init() {
        TransactionListener transactionListener = new TransactionListener() {
            public LocalTransactionState executeLocalTransaction(Message msg, Object arg) {
                int id = (Integer) arg;
                if(id == 1) {
                    System.out.println("executeLocalTransaction id:" + id + " UNKNOW");
                    return LocalTransactionState.UNKNOW;
                }
                if(id == 2) {
                    System.out.println("executeLocalTransaction id:" + id + " UNKNOW");
                    return LocalTransactionState.UNKNOW;
                }
                if(id == 3) {
                    System.out.println("executeLocalTransaction id:" + id + " ROLLBACK_MESSAGE");
                    return LocalTransactionState.ROLLBACK_MESSAGE;
                }
                if(id == 4) {
                    System.out.println("executeLocalTransaction id:" + id + " UNKNOW");
                    return LocalTransactionState.UNKNOW;
                }
                return LocalTransactionState.COMMIT_MESSAGE;
            }

            @Override
            public LocalTransactionState checkLocalTransaction(MessageExt msg) {
                String key = msg.getKeys();
                int id = Integer.valueOf(key);
                System.out.println("checkLocalTransaction id:" + id);
                if(id == 1) {
                    System.out.println("UNKNOW");
                    return LocalTransactionState.UNKNOW;
                }
                if(id == 2) {
                    System.out.println("ROLLBACK_MESSAGE");
                    return LocalTransactionState.ROLLBACK_MESSAGE;
                }
                return LocalTransactionState.COMMIT_MESSAGE;
            }
        };
        producer = TestUtil.buildProducer("mqcloud-trans-topic-producer", "mqcloud-trans-topic", transactionListener);
        producer.start();
    }

