@AfterClass
    public static void tearDown() throws Exception {
        try {
            server.stopServer("CWWJP9991W", // From Eclipselink drop-and-create tables option
                              "WTRN0074E: Exception caught from before_completion synchronization operation" // RuntimeException test, expected
            );
        } finally {
            try {
                ServerConfiguration sc = server.getServerConfiguration();
                sc.getApplications().clear();
                server.updateServerConfiguration(sc);
                server.saveServerConfiguration();

                // Clean up loose bundles put in ${shared.app.dir}
                server.deleteDirectoryFromLibertyServerRoot("usr/shared/apps" + appName + "_EAR.ear");
                server.deleteDirectoryFromLibertyServerRoot("usr/shared/apps" + appName + "_JPALib.jar");
                server.deleteDirectoryFromLibertyServerRoot("usr/shared/apps" + appName + "_WAR.war");
                server.deleteDirectoryFromLibertyServerRoot("usr/shared/apps" + appName + "_EJB.jar");
                server.deleteDirectoryFromLibertyServerRoot("usr/shared/apps" + appName + "_JPA.jar");

                server.deleteFileFromLibertyServerRoot("apps/" + appName + "_EAR.ear.xml");
                server.deleteFileFromLibertyServerRoot("apps/DatabaseManagement.war");
            } catch (Throwable t) {
                t.printStackTrace();
            }
            bannerEnd(TestExample_EAR.class, timestart);
        }
    }

